functions:
/*  FUNCTION NAME:  LevelPaymentλ
    DESCRIPTION:*//**The level payment at the end of each period that repays a loan over a row of period rates, which may differ from period to period*/

LevelPaymentλ = LAMBDA(
//  Parameter Declaration
    [Principal],
    [Rates],
    [Balloon],
    LET(
    //  Help
        Help,           TRIM(TEXTSPLIT(
                            "FUNCTION:      →LevelPaymentλ(Principal, Rates, [Balloon])¶" &
                            "DESCRIPTION:   →The level payment at the end of each period that repays a loan over a row of period rates.¶NOTES!         →One payment for each rate, at the end of its period. Each period's balance¶               →grows by its own rate before the payment comes off, so after the last¶               →payment the balance is Balloon, 0 by default. Pass DayCountRateλ() as Rates¶               →to repay a loan under actual day counts. With the same rate in every period¶               →the result is -PMT(rate, periods, Principal, -Balloon). A positive Principal¶               →gives a positive payment. Principal and Balloon must be single numbers and¶               →Rates one row of numbers above -1; anything else returns a message, and an¶               →error shows.¶" &
                            "WEBPAGE:       →https://github.com/ryanduguid/Ozzit¶" &
                            "VERSION:       →1 Nov 2026¶" &
                            "PARAMETERS:    →¶" &
                            "Principal      →(Required) The amount borrowed at the start of the first period.¶" &
                            "Rates          →(Required) One row of interest rates, one for each period, such as the result of DayCountRateλ().¶" &
                            "Balloon        →(Optional: Default = 0) The balance left after the last payment.¶" &
                            "EXAMPLES:      →¶" &
                            "→Formula (oz is assumed to be the module's name)¶" &
                            "→=oz.LevelPaymentλ(1000, {0.01,0.01,0.01})¶" &
                            "→Result¶" &
                            "→340.02",
                            "→", "¶"
                        )),
    //  Check inputs - Omitted required arguments
        Help?,          OR(ISOMITTED(Principal), ISOMITTED(Rates)),
    //  Set defaults. A single blank Balloon is no balloon.
        Final,          IF(ISOMITTED(Balloon), 0, IF(AND(ROWS(Balloon) = 1, COLUMNS(Balloon) = 1), IF(Balloon = "", 0, Balloon), Balloon)),
    //  Arithmetic would read "1000" as 1000 and TRUE as 1. An error passes so it shows.
        Amounts?,       AND(ROWS(Principal) = 1, COLUMNS(Principal) = 1, ROWS(Final) = 1, COLUMNS(Final) = 1,
                            ISNUMBER(Principal) + ISERROR(Principal), ISNUMBER(Final) + ISERROR(Final)),
    //  A rate of -1 or below has no discount factor; a blank rate is a missing period
        ValidRates?,    AND(ROWS(Rates) = 1, IFERROR(ISNUMBER(Rates) * (Rates > -1) = 1, TRUE)),
        AmountMessage,  "LevelPaymentλ needs Principal and Balloon to be single numbers.",
        RatesMessage,   "LevelPaymentλ needs Rates to be one row of numbers above -1.",
    //  The loan is the present value of the payments and the balloon. Discounting each
    //  period end through the rates before it gives the factors, so the level payment is
    //  the principal less the balloon's present value, over the sum of the factors.
        Factors,        SCAN(1, Rates, LAMBDA(Acc, Rate, Acc / (1 + Rate))),
        Result,         (Principal - Final * TAKE(Factors, , -1)) / SUM(Factors),
    //  Return Result, Help or the message
        Return,         IF(Help?, 2, IF(NOT(Amounts?), 3, IF(NOT(ValidRates?), 4, 1))),
        CHOOSE( Return, Result, Help, AmountMessage, RatesMessage)
    )
);
